sys_script_include.script:
var MSSCustodyUnifiedUtils = Class.create();
MSSCustodyUnifiedUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getSysIds: function() {
        var table = this.getParameter('sysparm_table');
        var title = this.getParameter('sysparm_title');
        var active = this.getParameter('sysparm_active');
        var sysId = '';
        try {
            var ux_list_gr = new GlideRecord('sys_ux_list');
            ux_list_gr.addQuery('table', table);
            ux_list_gr.addQuery('title', title);
            ux_list_gr.addQuery('active', active);
            ux_list_gr.query();
            while (ux_list_gr.next()) {
                sysId = ux_list_gr.getValue('sys_id');
                //gs.info('MSSCustodyUnifiedUtils - sys_id = ' + sysId);
				break;
            }
        } catch (e) {
            return 'Error: ' + e.message;
        }

        //gs.info('MSSCustodyUnifiedUtils - sysId = ' + sysId);
        return sysId;

    },

    type: 'MSSCustodyUnifiedUtils'
});
